using System.Text.Json;using WpeAgent.RuntimeContracts;using WpeAgent.RuntimeServices;using 币安量化机器人.Core.Models;
namespace WPE.Tests;
public sealed class UiDiagnosticProjectionTests
{
 [Fact]public void RuntimeSnapshotNeverProjectsRawExternalFailureText(){const string secret="sk-ui-secret-token-123456",account="account-448899";var raw=$"Authorization: Bearer {secret} endpoint=https://api.example.com/v1/orders?api_key={secret} account-id={account} prompt={secret} response={secret}";var now=DateTime.UtcNow;var state=new SystemState{LastUpdated=now,LastError=raw,RiskSummary=raw,LastReason=raw,DecisionDiagnostics=raw,NewsSummary=raw};var snapshot=RuntimeSnapshotFactory.Create(state,now,tradingState:RuntimeTradingState.Error(raw),backtestState:RuntimeBacktestState.Error(raw),auditState:RuntimeAuditState.Error(raw));var json=JsonSerializer.Serialize(snapshot);foreach(var forbidden in new[]{secret,account,"api.example.com","prompt=","response="})Assert.DoesNotContain(forbidden,json,StringComparison.OrdinalIgnoreCase);var diagnostic=Assert.IsType<RuntimeDiagnosticV1>(snapshot.Diagnostic.Value);Assert.StartsWith("WPE-",diagnostic.Code);Assert.Equal("Runtime operation failed.",diagnostic.Summary);Assert.Equal(RuntimeCollectionState.Error,snapshot.Positions.State);Assert.Contains("WPE-",snapshot.Positions.Message);}
 [Fact]public void UiSourcesDoNotDirectlyRenderExceptionMessages(){var root=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"..","..","..",".."));var text=File.ReadAllText(Path.Combine(root,"ReferenceUiWindow.xaml.cs"))+File.ReadAllText(Path.Combine(root,"SetupWindow.xaml.cs"));Assert.DoesNotContain("MessageBox.Show(ex.Message",text);Assert.DoesNotContain("Text=ex.Message",text);}
}
